@import "@fontsource-variable/figtree";

/* Light (faithful): a white page, pure black ink, black bands and buttons, #999 greys for
   secondary text. Rare accents: an electric periwinkle (#4a53ff) highlight for the strip and
   chips, a navy (#03245d) secondary band, green (#178c41) figures (chart-5). chart-1..4 are the
   plan-card pastels: steel blue, mauve, mint, cream. The glow is the warm amber of the hero. */
:root {
  --background: #ffffff;
  --foreground: #000000;
  --card: #ffffff;
  --card-foreground: #000000;
  --popover: #ffffff;
  --popover-foreground: #000000;
  --primary: #000000;
  --primary-foreground: #ffffff;
  --secondary: #03245d;
  --secondary-foreground: #ffffff;
  --muted: #f1f1f1;
  --muted-foreground: #777777;
  --accent: #ececec;
  --accent-foreground: #000000;
  --destructive: #d6283c;
  --destructive-foreground: #ffffff;
  --border: #999999;
  --input: #999999;
  --ring: #4a53ff;
  --highlight: #4a53ff;
  --highlight-foreground: #ffffff;
  --glow: #c0632a;
  --chart-1: #479ac2;
  --chart-2: #bdb0be;
  --chart-3: #b7e6db;
  --chart-4: #f6fee8;
  --chart-5: #178c41;
  --sidebar: #ffffff;
  --sidebar-foreground: #000000;
  --sidebar-primary: #000000;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #f1f1f1;
  --sidebar-accent-foreground: #000000;
  --sidebar-border: #e2e2e2;
  --sidebar-ring: #4a53ff;

  --typeface-body: "Figtree Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Figtree Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 1.125rem; /* 18px carousel cards */
  --page-width: 82.5rem; /* 1280px of content + two 20px gutters */
  --page-gutter: 1.25rem;
  --section-y: 3.125rem;
}

/* Dark sibling: a near-black page with #1a1a1a cards (the original's black bands sit on the
   card colour here), white ink, the same periwinkle and amber, deeper plan pastels. */
.dark {
  --background: #0b0b0b;
  --foreground: #ffffff;
  --card: #1a1a1a;
  --card-foreground: #ffffff;
  --popover: #1a1a1a;
  --popover-foreground: #ffffff;
  --primary: #ffffff;
  --primary-foreground: #000000;
  --secondary: #0a3a8a;
  --secondary-foreground: #ffffff;
  --muted: #222222;
  --muted-foreground: #999999;
  --accent: #2a2a2a;
  --accent-foreground: #ffffff;
  --destructive: #ff5a6a;
  --destructive-foreground: #ffffff;
  --border: #6f6f6f;
  --input: #6f6f6f;
  --ring: #7c83ff;
  --highlight: #6a72ff;
  --highlight-foreground: #ffffff;
  --glow: #c0632a;
  --chart-1: #24546d;
  --chart-2: #4a3f4b;
  --chart-3: #24524a;
  --chart-4: #2e3324;
  --chart-5: #3cc26c;
  --sidebar: #1a1a1a;
  --sidebar-foreground: #ffffff;
  --sidebar-primary: #ffffff;
  --sidebar-primary-foreground: #000000;
  --sidebar-accent: #2a2a2a;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: #333333;
  --sidebar-ring: #7c83ff;
}
